import { TriviaQuestion } from '../trivia-types'

export const PRESIDENTS_QUESTIONS: TriviaQuestion[] = [
  { id: 'pres-1', category: 'presidents', difficulty: 'easy', question: 'Who was the first President of the United States?', answer: 'George Washington', options: ['John Adams', 'George Washington', 'Thomas Jefferson', 'Benjamin Franklin'], explanation: 'George Washington served two terms from 1789 to 1797 and set many precedents for the office. He is the only president to have been unanimously elected by the Electoral College.' },
  { id: 'pres-2', category: 'presidents', difficulty: 'easy', question: 'Who was president during the Civil War?', answer: 'Abraham Lincoln', options: ['Abraham Lincoln', 'Andrew Johnson', 'Ulysses S. Grant', 'James Buchanan'], explanation: 'Abraham Lincoln served from 1861 to 1865 and led the Union through the Civil War. He issued the Emancipation Proclamation in 1863 and was assassinated by John Wilkes Booth at Ford\'s Theatre.' },
  { id: 'pres-3', category: 'presidents', difficulty: 'easy', question: 'What president is on the one-dollar bill?', answer: 'George Washington', options: ['Abraham Lincoln', 'George Washington', 'Thomas Jefferson', 'Andrew Jackson'], explanation: 'George Washington has been on the one-dollar bill since 1869. He also appears on the quarter, which has featured his likeness since 1932.' },
  { id: 'pres-4', category: 'presidents', difficulty: 'easy', question: 'Who was the president during the Great Depression and World War II?', answer: 'Franklin D. Roosevelt', options: ['Harry Truman', 'Franklin D. Roosevelt', 'Herbert Hoover', 'Dwight Eisenhower'], explanation: 'FDR served an unprecedented four terms from 1933 to 1945, the only president to serve more than two terms. The 22nd Amendment, ratified in 1951, later limited presidents to two terms.' },
  { id: 'pres-5', category: 'presidents', difficulty: 'easy', question: 'What president purchased the Louisiana Territory from France?', answer: 'Thomas Jefferson', options: ['George Washington', 'Thomas Jefferson', 'James Madison', 'James Monroe'], explanation: 'Thomas Jefferson bought the Louisiana Territory in 1803 for approximately $15 million, doubling the size of the nation. He then sent Lewis and Clark to explore the new territory.' },
  { id: 'pres-6', category: 'presidents', difficulty: 'easy', question: 'Who was the first president to live in the White House?', answer: 'John Adams', options: ['George Washington', 'John Adams', 'Thomas Jefferson', 'James Madison'], explanation: 'John Adams moved into the White House in November 1800, while the building was still under construction. George Washington is the only president who never lived in the White House.' },
  { id: 'pres-7', category: 'presidents', difficulty: 'easy', question: 'What president is on Mount Rushmore alongside Washington, Jefferson, and Lincoln?', answer: 'Theodore Roosevelt', options: ['Franklin D. Roosevelt', 'Theodore Roosevelt', 'Andrew Jackson', 'Woodrow Wilson'], explanation: 'Mount Rushmore was carved between 1927 and 1941 by sculptor Gutzon Borglum. Theodore Roosevelt was included for his role in building the Panama Canal and conserving natural resources.' },
  { id: 'pres-8', category: 'presidents', difficulty: 'easy', question: 'Who was the youngest person to become president?', answer: 'Theodore Roosevelt', options: ['John F. Kennedy', 'Theodore Roosevelt', 'Bill Clinton', 'Barack Obama'], explanation: 'Theodore Roosevelt became president at age 42 after McKinley\'s assassination in 1901. JFK was the youngest elected president at 43, but TR was younger when he assumed office.' },
  { id: 'pres-9', category: 'presidents', difficulty: 'easy', question: 'What president resigned from office due to the Watergate scandal?', answer: 'Richard Nixon', options: ['Lyndon Johnson', 'Richard Nixon', 'Gerald Ford', 'Jimmy Carter'], explanation: 'Richard Nixon resigned on August 9, 1974, the only president ever to resign. His successor, Gerald Ford, controversially pardoned Nixon for any crimes he may have committed while in office.' },
  { id: 'pres-10', category: 'presidents', difficulty: 'easy', question: 'Who was the first African American president?', answer: 'Barack Obama', options: ['Barack Obama', 'Bill Clinton', 'Colin Powell', 'Joe Biden'], explanation: 'Barack Obama was elected the 44th president in 2008 and served two terms. Before his presidency, he served as a U.S. Senator from Illinois.' },
  { id: 'pres-11', category: 'presidents', difficulty: 'easy', question: 'What document did Abraham Lincoln issue to free enslaved people in Confederate states?', answer: 'The Emancipation Proclamation', options: ['The Bill of Rights', 'The Emancipation Proclamation', 'The Gettysburg Address', 'The 13th Amendment'], explanation: 'The Emancipation Proclamation took effect on January 1, 1863, freeing enslaved people in Confederate states. The 13th Amendment, ratified in 1865, formally abolished slavery throughout the entire United States.' },
  { id: 'pres-12', category: 'presidents', difficulty: 'easy', question: 'What president dropped the atomic bombs on Japan to end World War II?', answer: 'Harry S. Truman', options: ['Franklin D. Roosevelt', 'Harry S. Truman', 'Dwight Eisenhower', 'Douglas MacArthur'], explanation: 'Truman authorized the bombings of Hiroshima (August 6, 1945) and Nagasaki (August 9, 1945). FDR had died in April 1945, and Truman only learned about the Manhattan Project after becoming president.' },
  { id: 'pres-13', category: 'presidents', difficulty: 'easy', question: 'Who was president when the United States declared independence in 1776?', answer: 'There was no president yet', options: ['George Washington', 'There was no president yet', 'John Adams', 'Benjamin Franklin'], explanation: 'The Declaration of Independence was signed in 1776, but the presidency wasn\'t established until 1789 under the Constitution. The Continental Congress was led by a president of Congress, not the same as the U.S. president.' },
  { id: 'pres-14', category: 'presidents', difficulty: 'easy', question: 'What president is known for the phrase "Ask not what your country can do for you"?', answer: 'John F. Kennedy', options: ['Franklin D. Roosevelt', 'John F. Kennedy', 'Ronald Reagan', 'Barack Obama'], explanation: 'JFK spoke these words in his inaugural address on January 20, 1961. He was assassinated in Dallas, Texas, on November 22, 1963.' },
  { id: 'pres-15', category: 'presidents', difficulty: 'easy', question: 'What presidential retreat is located in Maryland?', answer: 'Camp David', options: ['Camp David', 'Mar-a-Lago', 'Mount Vernon', 'The Western White House'], explanation: 'Camp David has been the presidential country retreat since FDR renamed it Shangri-La in 1942; Eisenhower renamed it Camp David after his grandson. The Camp David Accords, a peace agreement between Egypt and Israel, were negotiated there in 1978.' },
  { id: 'pres-16', category: 'presidents', difficulty: 'easy', question: 'What is the name of the president\'s official airplane?', answer: 'Air Force One', options: ['Air Force One', 'Eagle One', 'Executive One', 'Presidential Express'], explanation: 'Air Force One is technically the call sign for any Air Force aircraft carrying the president, not a specific plane. The current fleet consists of two Boeing 747-200B aircraft (VC-25A).' },
  { id: 'pres-17', category: 'presidents', difficulty: 'easy', question: 'How many terms can a U.S. president serve?', answer: 'Two', options: ['One', 'Two', 'Three', 'No limit'], explanation: 'The 22nd Amendment, ratified in 1951, limits presidents to two terms. It was passed in response to FDR serving four terms, though Washington had set the two-term precedent by voluntarily stepping down.' },
  { id: 'pres-18', category: 'presidents', difficulty: 'easy', question: 'What branch of government does the president head?', answer: 'Executive', options: ['Legislative', 'Executive', 'Judicial', 'Congressional'], explanation: 'The president heads the executive branch, which enforces laws. The legislative branch (Congress) makes laws, and the judicial branch (Supreme Court) interprets them.' },
  { id: 'pres-19', category: 'presidents', difficulty: 'easy', question: 'Who was the only president to serve two non-consecutive terms?', answer: 'Grover Cleveland', options: ['Grover Cleveland', 'Theodore Roosevelt', 'Andrew Jackson', 'John Quincy Adams'], explanation: 'Grover Cleveland served as the 22nd president (1885-1889) and 24th president (1893-1897). He lost to Benjamin Harrison in 1888 despite winning the popular vote, then defeated Harrison in the rematch four years later.' },
  { id: 'pres-20', category: 'presidents', difficulty: 'easy', question: 'What amendment gave women the right to vote?', answer: '19th Amendment', options: ['15th Amendment', '17th Amendment', '19th Amendment', '21st Amendment'], explanation: 'The 19th Amendment was ratified on August 18, 1920, after decades of activism by suffragists like Susan B. Anthony and Elizabeth Cady Stanton. It states that the right to vote shall not be denied on account of sex.' },
  { id: 'pres-21', category: 'presidents', difficulty: 'easy', question: 'Who was the tallest U.S. president at 6 feet 4 inches?', answer: 'Abraham Lincoln', options: ['George Washington', 'Abraham Lincoln', 'Lyndon Johnson', 'Donald Trump'], explanation: 'Abraham Lincoln stood 6\'4" and was known for his distinctive stovepipe hat, which made him appear even taller. The shortest president was James Madison at 5\'4".' },
  { id: 'pres-22', category: 'presidents', difficulty: 'easy', question: 'What Supreme Court case established the principle of judicial review?', answer: 'Marbury v. Madison', options: ['Marbury v. Madison', 'Dred Scott v. Sandford', 'McCulloch v. Maryland', 'Gibbons v. Ogden'], explanation: 'Marbury v. Madison (1803) established that the Supreme Court has the power to declare laws unconstitutional. Chief Justice John Marshall wrote the landmark opinion, fundamentally shaping the balance of power in government.' },
  { id: 'pres-23', category: 'presidents', difficulty: 'easy', question: 'What president was a famous World War II general before entering politics?', answer: 'Dwight D. Eisenhower', options: ['Harry Truman', 'Dwight D. Eisenhower', 'John F. Kennedy', 'George H.W. Bush'], explanation: 'Eisenhower served as Supreme Commander of Allied Forces in Europe during WWII and planned the D-Day invasion. He served two terms as president from 1953 to 1961.' },
  { id: 'pres-24', category: 'presidents', difficulty: 'easy', question: 'What is the minimum age to become president of the United States?', answer: '35', options: ['25', '30', '35', '40'], explanation: 'Article II of the Constitution requires the president to be at least 35 years old, a natural-born citizen, and a resident of the United States for at least 14 years. The youngest president, Theodore Roosevelt, took office at 42.' },
  { id: 'pres-25', category: 'presidents', difficulty: 'easy', question: 'What amendment abolished slavery in the United States?', answer: '13th Amendment', options: ['13th Amendment', '14th Amendment', '15th Amendment', '19th Amendment'], explanation: 'The 13th Amendment was ratified on December 6, 1865, after the end of the Civil War. The 14th Amendment granted citizenship to formerly enslaved people, and the 15th gave Black men the right to vote.' },
  { id: 'pres-26', category: 'presidents', difficulty: 'easy', question: 'Who became president after JFK was assassinated?', answer: 'Lyndon B. Johnson', options: ['Richard Nixon', 'Lyndon B. Johnson', 'Hubert Humphrey', 'Robert F. Kennedy'], explanation: 'LBJ was sworn in aboard Air Force One just hours after Kennedy\'s assassination on November 22, 1963. He went on to win the 1964 election in a landslide and passed major civil rights and social legislation.' },
  { id: 'pres-27', category: 'presidents', difficulty: 'easy', question: 'What constitutional amendment prohibits cruel and unusual punishment?', answer: '8th Amendment', options: ['5th Amendment', '6th Amendment', '8th Amendment', '10th Amendment'], explanation: 'The 8th Amendment is part of the Bill of Rights, ratified in 1791. It also prohibits excessive bail and excessive fines.' },
  { id: 'pres-28', category: 'presidents', difficulty: 'easy', question: 'What president is associated with the New Deal programs during the Great Depression?', answer: 'Franklin D. Roosevelt', options: ['Herbert Hoover', 'Franklin D. Roosevelt', 'Harry Truman', 'Calvin Coolidge'], explanation: 'FDR launched the New Deal in 1933, creating programs like Social Security, the WPA, and the CCC. These programs fundamentally expanded the role of the federal government in American life.' },
  { id: 'pres-29', category: 'presidents', difficulty: 'easy', question: 'What founding father is on the $100 bill but was never president?', answer: 'Benjamin Franklin', options: ['Alexander Hamilton', 'Benjamin Franklin', 'John Jay', 'Samuel Adams'], explanation: 'Benjamin Franklin was a diplomat, inventor, writer, and one of the Founding Fathers. Alexander Hamilton, also never president, appears on the $10 bill.' },
  { id: 'pres-30', category: 'presidents', difficulty: 'easy', question: 'What president famously said "Mr. Gorbachev, tear down this wall"?', answer: 'Ronald Reagan', options: ['Richard Nixon', 'Ronald Reagan', 'George H.W. Bush', 'Jimmy Carter'], explanation: 'Reagan delivered this speech at the Brandenburg Gate in Berlin on June 12, 1987. The Berlin Wall fell two years later in November 1989, though it was primarily due to internal pressures within East Germany and the Soviet bloc.' },
  { id: 'pres-31', category: 'presidents', difficulty: 'easy', question: 'What is the Bill of Rights?', answer: 'The first ten amendments to the Constitution', options: ['The Declaration of Independence', 'The first ten amendments to the Constitution', 'The Articles of Confederation', 'The Federalist Papers'], explanation: 'The Bill of Rights was ratified on December 15, 1791, and guarantees fundamental liberties like freedom of speech, religion, and the press. James Madison is considered the primary author.' },
  { id: 'pres-32', category: 'presidents', difficulty: 'easy', question: 'What president served during the War of 1812?', answer: 'James Madison', options: ['Thomas Jefferson', 'James Madison', 'James Monroe', 'John Adams'], explanation: 'James Madison led the nation during the War of 1812 against Britain, during which the White House was burned. The war ended with the Treaty of Ghent in 1814, essentially restoring pre-war boundaries.' },
  { id: 'pres-33', category: 'presidents', difficulty: 'easy', question: 'How many justices serve on the U.S. Supreme Court?', answer: 'Nine', options: ['Seven', 'Nine', 'Eleven', 'Thirteen'], explanation: 'The Supreme Court has had nine justices since 1869, though the Constitution does not specify a number. The number has varied historically from as few as five to as many as ten.' },
  { id: 'pres-34', category: 'presidents', difficulty: 'easy', question: 'What president was known as "Honest Abe"?', answer: 'Abraham Lincoln', options: ['George Washington', 'Abraham Lincoln', 'Andrew Jackson', 'James Garfield'], explanation: 'Lincoln earned the nickname during his years as a lawyer in Illinois for his reputation for integrity. He is consistently ranked by historians as one of the greatest American presidents.' },
  { id: 'pres-35', category: 'presidents', difficulty: 'easy', question: 'What amendment guarantees freedom of speech and religion?', answer: '1st Amendment', options: ['1st Amendment', '2nd Amendment', '4th Amendment', '5th Amendment'], explanation: 'The 1st Amendment protects five freedoms: religion, speech, press, assembly, and the right to petition the government. It is arguably the most well-known amendment in the Bill of Rights.' },
  { id: 'pres-36', category: 'presidents', difficulty: 'medium', question: 'What president established the national park system by signing the Antiquities Act of 1906?', answer: 'Theodore Roosevelt', options: ['Woodrow Wilson', 'Theodore Roosevelt', 'William Taft', 'Calvin Coolidge'], explanation: 'Theodore Roosevelt used the Antiquities Act to protect roughly 230 million acres of public land during his presidency. He established 5 national parks, 18 national monuments, and 150 national forests.' },
  { id: 'pres-37', category: 'presidents', difficulty: 'medium', question: 'Who was the only president to also serve as Chief Justice of the Supreme Court?', answer: 'William Howard Taft', options: ['John Quincy Adams', 'William Howard Taft', 'Herbert Hoover', 'Warren G. Harding'], explanation: 'Taft served as president from 1909 to 1913, then was appointed Chief Justice by Warren Harding in 1921. He reportedly said the presidency was the role he least enjoyed and preferred the Court.' },
  { id: 'pres-38', category: 'presidents', difficulty: 'medium', question: 'What was the first state to ratify the U.S. Constitution?', answer: 'Delaware', options: ['Virginia', 'Massachusetts', 'Pennsylvania', 'Delaware'], explanation: 'Delaware ratified the Constitution on December 7, 1787, earning its nickname "The First State." All 13 states had ratified by May 1790, with Rhode Island being the last.' },
  { id: 'pres-39', category: 'presidents', difficulty: 'medium', question: 'What president issued the Monroe Doctrine, warning European powers to stay out of the Americas?', answer: 'James Monroe', options: ['James Monroe', 'John Quincy Adams', 'Andrew Jackson', 'James Madison'], explanation: 'The Monroe Doctrine was proclaimed in 1823 and became a cornerstone of American foreign policy. It was largely drafted by Secretary of State John Quincy Adams and warned against European colonization in the Western Hemisphere.' },
  { id: 'pres-40', category: 'presidents', difficulty: 'medium', question: 'Which two presidents died on the same day — July 4, 1826?', answer: 'John Adams and Thomas Jefferson', options: ['John Adams and Thomas Jefferson', 'James Monroe and James Madison', 'George Washington and John Adams', 'Thomas Jefferson and James Madison'], explanation: 'Adams and Jefferson both died on July 4, 1826, exactly 50 years after the Declaration of Independence. Adams\'s last words were reportedly "Thomas Jefferson survives," not knowing Jefferson had died a few hours earlier.' },
  { id: 'pres-41', category: 'presidents', difficulty: 'medium', question: 'What scandal involved the illegal sale of government oil reserves during the Harding administration?', answer: 'Teapot Dome', options: ['Watergate', 'Teapot Dome', 'Credit Mobilier', 'Iran-Contra'], explanation: 'Secretary of the Interior Albert Fall secretly leased federal oil reserves at Teapot Dome, Wyoming, to private companies in exchange for bribes. Fall became the first Cabinet member to go to prison for crimes committed while in office.' },
  { id: 'pres-42', category: 'presidents', difficulty: 'medium', question: 'What president negotiated the Camp David Accords between Egypt and Israel?', answer: 'Jimmy Carter', options: ['Richard Nixon', 'Jimmy Carter', 'Ronald Reagan', 'Gerald Ford'], explanation: 'The Camp David Accords were signed in September 1978 by Egyptian President Anwar Sadat and Israeli Prime Minister Menachem Begin. This was the first peace agreement between Israel and an Arab nation.' },
  { id: 'pres-43', category: 'presidents', difficulty: 'medium', question: 'What president was impeached for violating the Tenure of Office Act in 1868?', answer: 'Andrew Johnson', options: ['Andrew Johnson', 'Andrew Jackson', 'Ulysses S. Grant', 'James Buchanan'], explanation: 'Andrew Johnson was impeached by the House for firing Secretary of War Edwin Stanton without Senate approval. He was acquitted in the Senate by a single vote and finished his term.' },
  { id: 'pres-44', category: 'presidents', difficulty: 'medium', question: 'What president signed the Civil Rights Act of 1964?', answer: 'Lyndon B. Johnson', options: ['John F. Kennedy', 'Lyndon B. Johnson', 'Dwight Eisenhower', 'Richard Nixon'], explanation: 'LBJ signed the Civil Rights Act on July 2, 1964, outlawing discrimination based on race, color, religion, sex, or national origin. JFK had proposed the legislation before his assassination, but it was LBJ\'s political skill that got it passed.' },
  { id: 'pres-45', category: 'presidents', difficulty: 'medium', question: 'What landmark Supreme Court case declared school segregation unconstitutional?', answer: 'Brown v. Board of Education', options: ['Plessy v. Ferguson', 'Brown v. Board of Education', 'Roe v. Wade', 'Miranda v. Arizona'], explanation: 'Brown v. Board of Education (1954) overturned the "separate but equal" doctrine established by Plessy v. Ferguson in 1896. Chief Justice Earl Warren wrote the unanimous opinion that segregated schools were "inherently unequal."' },
  { id: 'pres-46', category: 'presidents', difficulty: 'medium', question: 'Who was the first vice president of the United States?', answer: 'John Adams', options: ['Thomas Jefferson', 'John Adams', 'Aaron Burr', 'Alexander Hamilton'], explanation: 'John Adams served as vice president under George Washington from 1789 to 1797. He famously called it "the most insignificant office that ever the invention of man contrived."' },
  { id: 'pres-47', category: 'presidents', difficulty: 'medium', question: 'What amendment lowered the voting age from 21 to 18?', answer: '26th Amendment', options: ['24th Amendment', '25th Amendment', '26th Amendment', '27th Amendment'], explanation: 'The 26th Amendment was ratified in 1971, largely driven by the argument that if 18-year-olds could be drafted to fight in Vietnam, they should be able to vote. It was ratified faster than any other amendment — in just 100 days.' },
  { id: 'pres-48', category: 'presidents', difficulty: 'medium', question: 'What president completed the purchase of Alaska from Russia in 1867?', answer: 'Andrew Johnson', options: ['Abraham Lincoln', 'Andrew Johnson', 'Ulysses S. Grant', 'James Buchanan'], explanation: 'Secretary of State William Seward negotiated the purchase for $7.2 million, roughly 2 cents per acre. Critics initially mocked it as "Seward\'s Folly" until gold was discovered there in the 1890s.' },
  { id: 'pres-49', category: 'presidents', difficulty: 'medium', question: 'What amendment ended Prohibition?', answer: '21st Amendment', options: ['18th Amendment', '19th Amendment', '21st Amendment', '22nd Amendment'], explanation: 'The 21st Amendment, ratified in 1933, repealed the 18th Amendment which had banned alcohol since 1920. It is the only amendment to repeal another amendment.' },
  { id: 'pres-50', category: 'presidents', difficulty: 'medium', question: 'Who was the only president never elected as either president or vice president?', answer: 'Gerald Ford', options: ['John Tyler', 'Gerald Ford', 'Chester Arthur', 'Andrew Johnson'], explanation: 'Gerald Ford was appointed vice president after Spiro Agnew resigned in 1973, then became president after Nixon resigned in 1974. He is the only person to hold both offices without being elected to either.' },
  { id: 'pres-51', category: 'presidents', difficulty: 'medium', question: 'What Supreme Court case established the "Miranda rights" police must read to suspects?', answer: 'Miranda v. Arizona', options: ['Gideon v. Wainwright', 'Miranda v. Arizona', 'Mapp v. Ohio', 'Escobedo v. Illinois'], explanation: 'Miranda v. Arizona (1966) ruled that suspects must be informed of their rights before interrogation, including the right to remain silent and the right to an attorney. Ernesto Miranda\'s confession was thrown out because he had not been informed of these rights.' },
  { id: 'pres-52', category: 'presidents', difficulty: 'medium', question: 'What president is associated with the phrase "Manifest Destiny" and westward expansion?', answer: 'James K. Polk', options: ['Andrew Jackson', 'James K. Polk', 'James Monroe', 'Zachary Taylor'], explanation: 'Polk presided over the Mexican-American War and acquired California, Nevada, Utah, and parts of several other states. He is often called the most effective one-term president, having accomplished all his major campaign goals.' },
  { id: 'pres-53', category: 'presidents', difficulty: 'medium', question: 'What vice president fatally shot Alexander Hamilton in a duel?', answer: 'Aaron Burr', options: ['Aaron Burr', 'John C. Calhoun', 'Thomas Jefferson', 'George Clinton'], explanation: 'Aaron Burr killed Alexander Hamilton in a duel at Weehawken, New Jersey, on July 11, 1804, while still serving as vice president. Burr was charged with murder in both New York and New Jersey but was never tried.' },
  { id: 'pres-54', category: 'presidents', difficulty: 'medium', question: 'What president gave the Gettysburg Address?', answer: 'Abraham Lincoln', options: ['Abraham Lincoln', 'Andrew Johnson', 'Ulysses S. Grant', 'James Buchanan'], explanation: 'Lincoln delivered the Gettysburg Address on November 19, 1863, at the dedication of the Soldiers\' National Cemetery in Pennsylvania. The speech lasted just two minutes but became one of the most famous speeches in American history.' },
  { id: 'pres-55', category: 'presidents', difficulty: 'medium', question: 'What amendment guarantees the right to bear arms?', answer: '2nd Amendment', options: ['1st Amendment', '2nd Amendment', '4th Amendment', '5th Amendment'], explanation: 'The 2nd Amendment, ratified in 1791 as part of the Bill of Rights, states "the right of the people to keep and bear Arms, shall not be infringed." Its interpretation, particularly regarding militia versus individual rights, remains one of the most debated constitutional issues.' },
  { id: 'pres-56', category: 'presidents', difficulty: 'medium', question: 'What president was in office when the stock market crashed in 1929?', answer: 'Herbert Hoover', options: ['Calvin Coolidge', 'Herbert Hoover', 'Franklin D. Roosevelt', 'Warren G. Harding'], explanation: 'Herbert Hoover took office in March 1929, just months before the crash in October. He was widely blamed for the Great Depression, and shantytowns of homeless people were mockingly called "Hoovervilles."' },
  { id: 'pres-57', category: 'presidents', difficulty: 'medium', question: 'What president ordered the desegregation of the U.S. military in 1948?', answer: 'Harry S. Truman', options: ['Dwight Eisenhower', 'Harry S. Truman', 'Franklin D. Roosevelt', 'John F. Kennedy'], explanation: 'Truman signed Executive Order 9981 on July 26, 1948, declaring equality of treatment in the armed forces regardless of race. Full implementation took several years and was largely completed during the Korean War.' },
  { id: 'pres-58', category: 'presidents', difficulty: 'medium', question: 'What was the Iran-Contra affair?', answer: 'Secret arms sales to Iran to fund Nicaraguan rebels', options: ['A hostage crisis in Tehran', 'Secret arms sales to Iran to fund Nicaraguan rebels', 'An oil embargo by Middle Eastern nations', 'A CIA-backed coup in Iran'], explanation: 'During the Reagan administration, officials secretly sold arms to Iran and used the profits to fund Contra rebels in Nicaragua, violating congressional bans on such funding. The scandal led to several criminal convictions, though Reagan claimed he was unaware of the diversion.' },
  { id: 'pres-59', category: 'presidents', difficulty: 'medium', question: 'Who was the first Catholic president?', answer: 'John F. Kennedy', options: ['Al Smith', 'John F. Kennedy', 'Joe Biden', 'Richard Nixon'], explanation: 'JFK was elected in 1960, overcoming significant anti-Catholic prejudice at the time. Joe Biden later became the second Catholic president in 2021.' },
  { id: 'pres-60', category: 'presidents', difficulty: 'medium', question: 'What president created the Peace Corps?', answer: 'John F. Kennedy', options: ['Dwight Eisenhower', 'John F. Kennedy', 'Lyndon Johnson', 'Richard Nixon'], explanation: 'Kennedy established the Peace Corps by executive order on March 1, 1961. The organization sends American volunteers to developing countries to assist with education, health, and community development.' },
  { id: 'pres-61', category: 'presidents', difficulty: 'medium', question: 'What amendment protects against unreasonable searches and seizures?', answer: '4th Amendment', options: ['2nd Amendment', '4th Amendment', '5th Amendment', '6th Amendment'], explanation: 'The 4th Amendment requires law enforcement to obtain a warrant based on probable cause before conducting searches. It was inspired by colonial outrage over British "writs of assistance" that allowed unlimited searches.' },
  { id: 'pres-62', category: 'presidents', difficulty: 'medium', question: 'What president served the shortest term in office?', answer: 'William Henry Harrison', options: ['James Garfield', 'William Henry Harrison', 'Zachary Taylor', 'Warren G. Harding'], explanation: 'William Henry Harrison died just 31 days after his inauguration on April 4, 1841, likely of pneumonia. His inaugural address, delivered in cold rain without a coat, was the longest in presidential history at nearly two hours.' },
  { id: 'pres-63', category: 'presidents', difficulty: 'medium', question: 'What landmark case legalized same-sex marriage nationwide?', answer: 'Obergefell v. Hodges', options: ['Lawrence v. Texas', 'United States v. Windsor', 'Obergefell v. Hodges', 'Loving v. Virginia'], explanation: 'Obergefell v. Hodges (2015) ruled 5-4 that the fundamental right to marry is guaranteed to same-sex couples under the 14th Amendment. Justice Anthony Kennedy wrote the majority opinion.' },
  { id: 'pres-64', category: 'presidents', difficulty: 'medium', question: 'What political party was Abraham Lincoln a member of?', answer: 'Republican', options: ['Democrat', 'Republican', 'Whig', 'Federalist'], explanation: 'Lincoln was the first Republican president, elected in 1860. The Republican Party was founded in 1854 primarily in opposition to the expansion of slavery into new territories.' },
  { id: 'pres-65', category: 'presidents', difficulty: 'medium', question: 'What two presidents were father and son?', answer: 'John Adams and John Quincy Adams', options: ['John Adams and John Quincy Adams', 'Theodore and Franklin Roosevelt', 'William and Benjamin Harrison', 'George H.W. and George W. Bush'], explanation: 'John Adams (2nd president) and John Quincy Adams (6th president) were the first father-son pair. George H.W. Bush (41st) and George W. Bush (43rd) were the second. Note: the Harrisons were grandfather and grandson.' },
  { id: 'pres-66', category: 'presidents', difficulty: 'medium', question: 'What president was known as "Old Hickory"?', answer: 'Andrew Jackson', options: ['Andrew Jackson', 'Andrew Johnson', 'James Monroe', 'Zachary Taylor'], explanation: 'Andrew Jackson earned the nickname from his troops due to his toughness. He was the first president from the frontier (Tennessee) and championed what he called the "common man" against Eastern elites.' },
  { id: 'pres-67', category: 'presidents', difficulty: 'medium', question: 'What amendment established the direct election of U.S. senators by the people?', answer: '17th Amendment', options: ['15th Amendment', '16th Amendment', '17th Amendment', '19th Amendment'], explanation: 'Before the 17th Amendment was ratified in 1913, senators were chosen by state legislatures rather than by popular vote. The change was driven by widespread corruption in the selection process.' },
  { id: 'pres-68', category: 'presidents', difficulty: 'medium', question: 'What president annexed Texas and led the nation into the Mexican-American War?', answer: 'James K. Polk', options: ['John Tyler', 'James K. Polk', 'Zachary Taylor', 'Andrew Jackson'], explanation: 'Texas was annexed in 1845 just before Polk took office, but he provoked war with Mexico that resulted in the U.S. gaining California and the Southwest. He is considered one of the most consequential one-term presidents.' },
  { id: 'pres-69', category: 'presidents', difficulty: 'medium', question: 'What president\'s wife was known as "Dolley" and saved a portrait of Washington from the burning White House?', answer: 'James Madison', options: ['Thomas Jefferson', 'James Madison', 'James Monroe', 'John Adams'], explanation: 'Dolley Madison famously saved Gilbert Stuart\'s portrait of George Washington when the British burned the White House during the War of 1812. She was known as one of the most popular and socially influential first ladies.' },
  { id: 'pres-70', category: 'presidents', difficulty: 'medium', question: 'What amendment granted citizenship to all persons born in the United States?', answer: '14th Amendment', options: ['13th Amendment', '14th Amendment', '15th Amendment', '19th Amendment'], explanation: 'The 14th Amendment, ratified in 1868, also includes the Equal Protection Clause and Due Process Clause. It has been cited in more Supreme Court cases than any other amendment.' },
  { id: 'pres-71', category: 'presidents', difficulty: 'medium', question: 'Who was the first first lady to be elected to public office?', answer: 'Hillary Clinton', options: ['Eleanor Roosevelt', 'Hillary Clinton', 'Abigail Adams', 'Michelle Obama'], explanation: 'Hillary Clinton was elected U.S. Senator from New York in 2000, while her husband Bill was finishing his second term. She later served as Secretary of State and was the first woman nominated for president by a major party in 2016.' },
  { id: 'pres-72', category: 'presidents', difficulty: 'medium', question: 'Who is first in the presidential line of succession after the vice president?', answer: 'Speaker of the House', options: ['Secretary of State', 'Speaker of the House', 'Secretary of Defense', 'President Pro Tempore of the Senate'], explanation: 'The presidential succession order goes: Vice President, Speaker of the House, President Pro Tempore of the Senate, then Cabinet members starting with Secretary of State. This order was established by the Presidential Succession Act of 1947.' },
  { id: 'pres-73', category: 'presidents', difficulty: 'medium', question: 'What Supreme Court case ruled that corporations have free speech rights to spend on elections?', answer: 'Citizens United v. FEC', options: ['Citizens United v. FEC', 'Buckley v. Valeo', 'McCutcheon v. FEC', 'Shelby County v. Holder'], explanation: 'Citizens United v. FEC (2010) ruled 5-4 that the government cannot restrict independent political expenditures by corporations, associations, or labor unions. The decision was highly controversial and led to the rise of Super PACs.' },
  { id: 'pres-74', category: 'presidents', difficulty: 'medium', question: 'What amendment protects against self-incrimination ("pleading the Fifth")?', answer: '5th Amendment', options: ['4th Amendment', '5th Amendment', '6th Amendment', '8th Amendment'], explanation: 'The 5th Amendment protects against self-incrimination, double jeopardy, and guarantees due process of law. "Taking the Fifth" became common parlance during the McCarthy hearings of the 1950s.' },
  { id: 'pres-75', category: 'presidents', difficulty: 'medium', question: 'How many U.S. presidents have been assassinated while in office?', answer: 'Four', options: ['Two', 'Three', 'Four', 'Five'], explanation: 'The four assassinated presidents are: Abraham Lincoln (1865), James Garfield (1881), William McKinley (1901), and John F. Kennedy (1963). Several other presidents survived assassination attempts, including Theodore Roosevelt, who was shot but finished his speech.' },
  { id: 'pres-76', category: 'presidents', difficulty: 'medium', question: 'What president was known for the policy of "detente" with the Soviet Union and opened relations with China?', answer: 'Richard Nixon', options: ['John F. Kennedy', 'Richard Nixon', 'Gerald Ford', 'Jimmy Carter'], explanation: 'Nixon\'s 1972 visit to China was a historic diplomatic breakthrough after decades of hostility. His policy of detente with the Soviet Union led to the SALT I arms limitation treaty.' },
  { id: 'pres-77', category: 'presidents', difficulty: 'medium', question: 'What amendment established Prohibition, banning the sale of alcohol?', answer: '18th Amendment', options: ['16th Amendment', '18th Amendment', '20th Amendment', '21st Amendment'], explanation: 'The 18th Amendment was ratified in 1919 and took effect in 1920, beginning the Prohibition era. It led to widespread bootlegging and the rise of organized crime figures like Al Capone.' },
  { id: 'pres-78', category: 'presidents', difficulty: 'medium', question: 'What president won election in 2000 despite losing the popular vote, after a Supreme Court decision?', answer: 'George W. Bush', options: ['George W. Bush', 'Bill Clinton', 'Al Gore', 'John Kerry'], explanation: 'Bush v. Gore (2000) halted the Florida recount, effectively giving George W. Bush the state\'s electoral votes and the presidency. Al Gore won the popular vote by about 540,000 votes but lost the Electoral College 271-266.' },
  { id: 'pres-79', category: 'presidents', difficulty: 'medium', question: 'What president was a former peanut farmer from Georgia?', answer: 'Jimmy Carter', options: ['Jimmy Carter', 'Lyndon Johnson', 'Gerald Ford', 'Bill Clinton'], explanation: 'Jimmy Carter ran his family\'s peanut farm in Plains, Georgia, before entering politics. After his presidency, he became known for humanitarian work with Habitat for Humanity and won the Nobel Peace Prize in 2002.' },
  { id: 'pres-80', category: 'presidents', difficulty: 'medium', question: 'What founding father served as the first Secretary of the Treasury?', answer: 'Alexander Hamilton', options: ['Thomas Jefferson', 'Alexander Hamilton', 'John Adams', 'James Madison'], explanation: 'Hamilton served as Treasury Secretary under Washington and established the national banking system, the U.S. Mint, and a plan to pay off the national debt. He was killed in a duel with Vice President Aaron Burr in 1804.' },
  { id: 'pres-81', category: 'presidents', difficulty: 'medium', question: 'What president served as civil governor of the Philippines before becoming U.S. president?', answer: 'William Howard Taft', options: ['Theodore Roosevelt', 'William Howard Taft', 'Woodrow Wilson', 'Warren G. Harding'], explanation: 'Taft served as the first civil governor of the Philippines from 1901 to 1903. He later became the only person to serve as both president (1909-1913) and Chief Justice of the U.S. Supreme Court (1921-1930).' },
  { id: 'pres-82', category: 'presidents', difficulty: 'medium', question: 'What was the XYZ Affair during John Adams\'s presidency?', answer: 'French officials demanded bribes from American diplomats', options: ['A spy ring was discovered in Philadelphia', 'French officials demanded bribes from American diplomats', 'British ships attacked American merchants', 'A territorial dispute with Spain'], explanation: 'In 1797, French agents (referred to as X, Y, and Z) demanded bribes and a loan before they would negotiate with American envoys. The scandal outraged Americans and led to an undeclared naval war with France known as the Quasi-War.' },
  { id: 'pres-83', category: 'presidents', difficulty: 'medium', question: 'What president signed the Indian Removal Act, leading to the Trail of Tears?', answer: 'Andrew Jackson', options: ['James Monroe', 'Andrew Jackson', 'Martin Van Buren', 'John Tyler'], explanation: 'The Indian Removal Act of 1830 led to the forced relocation of approximately 60,000 Native Americans from the Southeast. The Cherokee removal in 1838, carried out under Martin Van Buren, is the most well-known, with an estimated 4,000 dying on the march.' },
  { id: 'pres-84', category: 'presidents', difficulty: 'medium', question: 'What amendment addresses presidential succession and disability?', answer: '25th Amendment', options: ['22nd Amendment', '23rd Amendment', '25th Amendment', '27th Amendment'], explanation: 'The 25th Amendment, ratified in 1967, clarifies the order of succession and allows for the vice president to serve as acting president during presidential disability. It was invoked in 1973 when Gerald Ford was appointed VP after Spiro Agnew resigned.' },
  { id: 'pres-85', category: 'presidents', difficulty: 'medium', question: 'What president won four consecutive presidential elections?', answer: 'Franklin D. Roosevelt', options: ['Franklin D. Roosevelt', 'Theodore Roosevelt', 'Woodrow Wilson', 'Abraham Lincoln'], explanation: 'FDR won elections in 1932, 1936, 1940, and 1944, serving as president until his death in April 1945. The 22nd Amendment was subsequently passed to ensure no one could serve more than two terms again.' },
  { id: 'pres-86', category: 'presidents', difficulty: 'medium', question: 'What Supreme Court case established the "separate but equal" doctrine?', answer: 'Plessy v. Ferguson', options: ['Dred Scott v. Sandford', 'Plessy v. Ferguson', 'Brown v. Board of Education', 'Gibbons v. Ogden'], explanation: 'Plessy v. Ferguson (1896) upheld racial segregation laws as long as facilities were "equal." Justice John Marshall Harlan wrote a famous dissent declaring the Constitution is "color-blind." The ruling stood until Brown v. Board overturned it in 1954.' },
  { id: 'pres-87', category: 'presidents', difficulty: 'medium', question: 'What president led the Rough Riders in the Spanish-American War?', answer: 'Theodore Roosevelt', options: ['William McKinley', 'Theodore Roosevelt', 'Ulysses S. Grant', 'Dwight Eisenhower'], explanation: 'Roosevelt led the Rough Riders, a volunteer cavalry regiment, in the Battle of San Juan Hill in Cuba in 1898. His war heroism helped propel him to the vice presidency and then the presidency after McKinley\'s assassination.' },
  { id: 'pres-88', category: 'presidents', difficulty: 'medium', question: 'What was the Whiskey Rebellion of 1794?', answer: 'A tax protest by western Pennsylvania farmers', options: ['A prohibition movement in New England', 'A tax protest by western Pennsylvania farmers', 'A Native American uprising', 'A trade dispute with Britain'], explanation: 'Farmers protested a federal excise tax on whiskey, which was their primary cash crop. President Washington personally led 13,000 militia troops to suppress the rebellion, establishing the federal government\'s authority to enforce its laws.' },
  { id: 'pres-89', category: 'presidents', difficulty: 'medium', question: 'What president was impeached in 1998 for perjury and obstruction of justice?', answer: 'Bill Clinton', options: ['Richard Nixon', 'Bill Clinton', 'George W. Bush', 'Donald Trump'], explanation: 'Clinton was impeached by the House related to the Monica Lewinsky scandal but was acquitted by the Senate in 1999. He is one of three presidents to be impeached; none have been removed by conviction.' },
  { id: 'pres-90', category: 'presidents', difficulty: 'medium', question: 'What document did Thomas Jefferson primarily author in 1776?', answer: 'The Declaration of Independence', options: ['The Constitution', 'The Declaration of Independence', 'The Bill of Rights', 'The Federalist Papers'], explanation: 'Jefferson drafted the Declaration of Independence at age 33, with edits from Benjamin Franklin and John Adams. The Continental Congress approved it on July 4, 1776, declaring independence from Great Britain.' },
  { id: 'pres-91', category: 'presidents', difficulty: 'hard', question: 'What president served the most time as an ex-president after leaving office?', answer: 'Jimmy Carter', options: ['Herbert Hoover', 'Jimmy Carter', 'John Adams', 'Gerald Ford'], explanation: 'Jimmy Carter left office in January 1981 and lived until December 2024, over 43 years as an ex-president. He surpassed Herbert Hoover, who held the record at 31 years.' },
  { id: 'pres-92', category: 'presidents', difficulty: 'hard', question: 'What president died 79 days after being shot by Charles Guiteau?', answer: 'James Garfield', options: ['William McKinley', 'James Garfield', 'Abraham Lincoln', 'William Henry Harrison'], explanation: 'Garfield was shot on July 2, 1881, at a Washington train station but survived for 79 days, dying September 19. Many historians believe he died not from the bullet itself but from infections caused by his doctors probing the wound with unwashed hands.' },
  { id: 'pres-93', category: 'presidents', difficulty: 'hard', question: 'What controversial Supreme Court ruling declared that enslaved people were not U.S. citizens?', answer: 'Dred Scott v. Sandford', options: ['Plessy v. Ferguson', 'Dred Scott v. Sandford', 'Marbury v. Madison', 'Gibbons v. Ogden'], explanation: 'The 1857 Dred Scott decision ruled that people of African descent could not be citizens and had no standing to sue in federal court. Chief Justice Roger Taney wrote the majority opinion, which is widely considered the worst Supreme Court decision in history.' },
  { id: 'pres-94', category: 'presidents', difficulty: 'hard', question: 'What president\'s administration was associated with the Alien and Sedition Acts?', answer: 'John Adams', options: ['George Washington', 'John Adams', 'Thomas Jefferson', 'James Madison'], explanation: 'The 1798 Alien and Sedition Acts made it harder for immigrants to become citizens and criminalized criticism of the government. Jefferson and Madison secretly authored the Virginia and Kentucky Resolutions opposing the acts as unconstitutional.' },
  { id: 'pres-95', category: 'presidents', difficulty: 'hard', question: 'What amendment was the last to be ratified, in 1992, dealing with congressional pay?', answer: '27th Amendment', options: ['25th Amendment', '26th Amendment', '27th Amendment', '28th Amendment'], explanation: 'The 27th Amendment prevents Congress from giving itself immediate pay raises; changes take effect only after the next election. It was originally proposed in 1789 as part of the original Bill of Rights but took 202 years to be ratified.' },
  { id: 'pres-96', category: 'presidents', difficulty: 'hard', question: 'Who was the first president to be impeached twice?', answer: 'Donald Trump', options: ['Bill Clinton', 'Donald Trump', 'Andrew Johnson', 'Richard Nixon'], explanation: 'Donald Trump was impeached first in December 2019 over the Ukraine affair and again in January 2021 for incitement of insurrection after the January 6 Capitol breach. He was acquitted by the Senate both times.' },
  { id: 'pres-97', category: 'presidents', difficulty: 'hard', question: 'What president signed the legislation establishing the Secret Service?', answer: 'Abraham Lincoln', options: ['Abraham Lincoln', 'Andrew Johnson', 'Ulysses S. Grant', 'Grover Cleveland'], explanation: 'Lincoln signed the legislation creating the Secret Service on April 14, 1865, the same day he was assassinated. The Secret Service was originally created to combat counterfeiting; presidential protection was not added until 1901 after McKinley\'s assassination.' },
  { id: 'pres-98', category: 'presidents', difficulty: 'hard', question: 'What vice president cast the most tie-breaking votes in the Senate?', answer: 'John Adams', options: ['John Adams', 'John C. Calhoun', 'Thomas Jefferson', 'Mike Pence'], explanation: 'John Adams cast 29 tie-breaking votes during his tenure as vice president from 1789 to 1797. The vice president serves as President of the Senate and may cast a vote only when there is a tie.' },
  { id: 'pres-99', category: 'presidents', difficulty: 'hard', question: 'What president kept a pet alligator in the White House, according to legend?', answer: 'John Quincy Adams', options: ['Andrew Jackson', 'John Quincy Adams', 'Theodore Roosevelt', 'Calvin Coolidge'], explanation: 'John Quincy Adams reportedly kept an alligator gifted by the Marquis de Lafayette in the East Room bathtub. Theodore Roosevelt was also famous for his menagerie, which included a badger, a bear, and a one-legged rooster.' },
  { id: 'pres-100', category: 'presidents', difficulty: 'hard', question: 'What doctrine stated that the U.S. would provide military or economic aid to countries resisting communism?', answer: 'Truman Doctrine', options: ['Monroe Doctrine', 'Truman Doctrine', 'Eisenhower Doctrine', 'Nixon Doctrine'], explanation: 'Announced in 1947, the Truman Doctrine initially provided aid to Greece and Turkey to resist Soviet influence. It marked the beginning of the U.S. policy of containment that defined the Cold War.' },
  { id: 'pres-101', category: 'presidents', difficulty: 'hard', question: 'What Supreme Court case ruled that the president does not have absolute immunity from civil litigation?', answer: 'Clinton v. Jones', options: ['United States v. Nixon', 'Clinton v. Jones', 'Nixon v. Fitzgerald', 'Trump v. Vance'], explanation: 'Clinton v. Jones (1997) ruled unanimously that a sitting president can be sued in federal court for acts done before the presidency. The case involved Paula Jones\'s sexual harassment lawsuit against Bill Clinton.' },
  { id: 'pres-102', category: 'presidents', difficulty: 'hard', question: 'What president established the Environmental Protection Agency (EPA) in 1970?', answer: 'Richard Nixon', options: ['Lyndon Johnson', 'Richard Nixon', 'Jimmy Carter', 'Gerald Ford'], explanation: 'Nixon created the EPA by executive order in response to growing public concern about pollution and environmental damage. He also signed the Clean Air Act and the National Environmental Policy Act.' },
  { id: 'pres-103', category: 'presidents', difficulty: 'hard', question: 'What was the "Saturday Night Massacre" during the Watergate scandal?', answer: 'Nixon fired the special prosecutor investigating him', options: ['Protesters were killed at a rally', 'Nixon fired the special prosecutor investigating him', 'White House tapes were destroyed', 'Cabinet members resigned in protest'], explanation: 'On October 20, 1973, Nixon ordered the firing of special prosecutor Archibald Cox, leading Attorney General Elliot Richardson and Deputy AG William Ruckelshaus to resign rather than carry out the order. Solicitor General Robert Bork ultimately fired Cox.' },
  { id: 'pres-104', category: 'presidents', difficulty: 'hard', question: 'What president gave the longest inaugural address in history, then died 31 days later?', answer: 'William Henry Harrison', options: ['Zachary Taylor', 'William Henry Harrison', 'James Garfield', 'Warren G. Harding'], explanation: 'Harrison\'s inaugural address lasted nearly two hours (about 8,445 words) and was delivered in cold, wet weather without a hat or coat. He developed pneumonia and died on April 4, 1841, setting off the first presidential succession crisis.' },
  { id: 'pres-105', category: 'presidents', difficulty: 'hard', question: 'What amendment gave Washington, D.C., residents the right to vote in presidential elections?', answer: '23rd Amendment', options: ['22nd Amendment', '23rd Amendment', '24th Amendment', '25th Amendment'], explanation: 'The 23rd Amendment, ratified in 1961, granted D.C. three electoral votes, the same as the least populous state. D.C. residents still have no voting representation in Congress.' },
  { id: 'pres-106', category: 'presidents', difficulty: 'hard', question: 'What president\'s cabinet included the "Kitchen Cabinet," an informal group of trusted advisors?', answer: 'Andrew Jackson', options: ['Andrew Jackson', 'Martin Van Buren', 'John Tyler', 'James Polk'], explanation: 'Jackson relied more on his informal advisors than his official Cabinet, and critics mockingly called them the "Kitchen Cabinet." The term has since entered the political lexicon to describe any president\'s unofficial inner circle.' },
  { id: 'pres-107', category: 'presidents', difficulty: 'hard', question: 'What president was elected in the most contentious election of 1876, decided by a congressional commission?', answer: 'Rutherford B. Hayes', options: ['Rutherford B. Hayes', 'Samuel Tilden', 'Ulysses S. Grant', 'James Garfield'], explanation: 'Hayes lost the popular vote to Samuel Tilden but won the presidency through the Compromise of 1877, in which disputed electoral votes were awarded to Hayes. In exchange, Hayes agreed to withdraw federal troops from the South, effectively ending Reconstruction.' },
  { id: 'pres-108', category: 'presidents', difficulty: 'hard', question: 'What Supreme Court case forced Nixon to turn over the Watergate tapes?', answer: 'United States v. Nixon', options: ['Nixon v. Fitzgerald', 'United States v. Nixon', 'Clinton v. Jones', 'Marbury v. Madison'], explanation: 'United States v. Nixon (1974) ruled unanimously that executive privilege does not grant a president absolute immunity from judicial process. Nixon resigned two weeks after the ruling, once the tapes revealed his involvement in the cover-up.' },
  { id: 'pres-109', category: 'presidents', difficulty: 'hard', question: 'What president survived an assassination attempt just 69 days into his first term?', answer: 'Ronald Reagan', options: ['Gerald Ford', 'Ronald Reagan', 'George H.W. Bush', 'Harry Truman'], explanation: 'John Hinckley Jr. shot Reagan on March 30, 1981, outside the Washington Hilton Hotel. Reagan famously quipped to surgeons, "I hope you\'re all Republicans." He recovered and served the remainder of his two terms.' },
  { id: 'pres-110', category: 'presidents', difficulty: 'hard', question: 'What was the Emoluments Clause controversy?', answer: 'Constitutional prohibition on presidents receiving gifts or payments from foreign governments', options: ['A debate over presidential salary increases', 'Constitutional prohibition on presidents receiving gifts or payments from foreign governments', 'A rule about presidential pension benefits', 'A restriction on lobbying after leaving office'], explanation: 'Article I, Section 9 of the Constitution prohibits federal officials from accepting "any present, Emolument, Office, or Title" from foreign states without congressional consent. It became a significant legal and political issue during the Trump administration.' },
  { id: 'pres-111', category: 'presidents', difficulty: 'hard', question: 'Who was the only president to earn a Ph.D.?', answer: 'Woodrow Wilson', options: ['John Adams', 'Woodrow Wilson', 'Barack Obama', 'Herbert Hoover'], explanation: 'Wilson earned his Ph.D. in political science from Johns Hopkins University in 1886. Before entering politics, he served as president of Princeton University and then governor of New Jersey.' },
  { id: 'pres-112', category: 'presidents', difficulty: 'hard', question: 'What president personally negotiated the end of the Russo-Japanese War, winning a Nobel Peace Prize?', answer: 'Theodore Roosevelt', options: ['Woodrow Wilson', 'Theodore Roosevelt', 'William Howard Taft', 'Calvin Coolidge'], explanation: 'Roosevelt brokered the Treaty of Portsmouth in 1905, ending the war between Russia and Japan. He was the first American to win the Nobel Peace Prize.' },
  { id: 'pres-113', category: 'presidents', difficulty: 'hard', question: 'What amendment abolished poll taxes in federal elections?', answer: '24th Amendment', options: ['23rd Amendment', '24th Amendment', '25th Amendment', '26th Amendment'], explanation: 'The 24th Amendment, ratified in 1964, banned poll taxes that had been used primarily to prevent Black citizens from voting in Southern states. The Supreme Court later extended this ban to state elections in Harper v. Virginia (1966).' },
  { id: 'pres-114', category: 'presidents', difficulty: 'hard', question: 'Who was the first president born in a hospital?', answer: 'Jimmy Carter', options: ['John F. Kennedy', 'Jimmy Carter', 'Richard Nixon', 'Lyndon Johnson'], explanation: 'Jimmy Carter was born at Wise Sanitarium in Plains, Georgia, on October 1, 1924. All previous presidents were born at home, as hospital births were not yet the norm.' },
  { id: 'pres-115', category: 'presidents', difficulty: 'hard', question: 'What president signed the Pendleton Civil Service Reform Act, establishing merit-based government hiring?', answer: 'Chester A. Arthur', options: ['James Garfield', 'Chester A. Arthur', 'Grover Cleveland', 'Rutherford B. Hayes'], explanation: 'Arthur signed the act in 1883 after Garfield\'s assassination by a disgruntled office-seeker highlighted the corruption of the spoils system. Ironically, Arthur had previously been a key figure in the patronage system as head of the New York Customs House.' },
  { id: 'pres-116', category: 'presidents', difficulty: 'hard', question: 'What was the "Corrupt Bargain" of 1824?', answer: 'Henry Clay allegedly helped John Quincy Adams win the presidency in exchange for being named Secretary of State', options: ['Andrew Jackson bribed electoral voters', 'Henry Clay allegedly helped John Quincy Adams win the presidency in exchange for being named Secretary of State', 'John Adams rigged the 1800 election', 'Thomas Jefferson made a deal with Aaron Burr'], explanation: 'When no candidate won a majority of electoral votes in 1824, the House chose Adams over Andrew Jackson despite Jackson winning the popular vote. When Adams then appointed Clay as Secretary of State, Jackson\'s supporters cried foul.' },
  { id: 'pres-117', category: 'presidents', difficulty: 'hard', question: 'What president\'s foreign policy was called "Big Stick Diplomacy"?', answer: 'Theodore Roosevelt', options: ['William McKinley', 'Theodore Roosevelt', 'Woodrow Wilson', 'William Howard Taft'], explanation: 'Roosevelt\'s approach was based on the West African proverb "Speak softly and carry a big stick." He used this philosophy to assert American power, particularly in Latin America and the construction of the Panama Canal.' },
  { id: 'pres-118', category: 'presidents', difficulty: 'hard', question: 'What landmark case ruled that flag burning is protected free speech?', answer: 'Texas v. Johnson', options: ['Tinker v. Des Moines', 'Texas v. Johnson', 'Brandenburg v. Ohio', 'Schenck v. United States'], explanation: 'Texas v. Johnson (1989) ruled 5-4 that burning the American flag as political protest is symbolic speech protected by the First Amendment. Justice William Brennan wrote the majority opinion, saying the government may not prohibit expression of an idea simply because society finds it disagreeable.' },
  { id: 'pres-119', category: 'presidents', difficulty: 'hard', question: 'What president created the Federal Reserve System in 1913?', answer: 'Woodrow Wilson', options: ['Theodore Roosevelt', 'Woodrow Wilson', 'William Howard Taft', 'Warren G. Harding'], explanation: 'Wilson signed the Federal Reserve Act on December 23, 1913, establishing the central banking system of the United States. The Fed was created in response to a series of financial panics, particularly the Panic of 1907.' },
  { id: 'pres-120', category: 'presidents', difficulty: 'hard', question: 'Who was the only president to be unanimously elected twice by the Electoral College?', answer: 'George Washington', options: ['George Washington', 'James Monroe', 'Franklin D. Roosevelt', 'Abraham Lincoln'], explanation: 'Washington received all electoral votes in both 1789 and 1792. James Monroe came close to unanimity in 1820, receiving all but one electoral vote — legend says one elector voted against him to preserve Washington\'s unique honor, though this story is likely apocryphal.' },
  { id: 'pres-121', category: 'presidents', difficulty: 'hard', question: 'What president established the precedent of a two-term limit?', answer: 'George Washington', options: ['George Washington', 'Thomas Jefferson', 'Andrew Jackson', 'James Madison'], explanation: 'Washington voluntarily declined to run for a third term in 1796, establishing a norm that lasted until FDR broke it in 1940. His Farewell Address warned against political parties and foreign entanglements.' },
  { id: 'pres-122', category: 'presidents', difficulty: 'hard', question: 'What is the Electoral Count Act, and why did it become controversial?', answer: 'A law governing how Congress counts electoral votes', options: ['A law governing how Congress counts electoral votes', 'A law setting the number of electors per state', 'A law requiring recounts in close elections', 'A law about campaign finance'], explanation: 'The Electoral Count Act of 1887 established procedures for Congress to count and certify electoral votes. It became controversial after the January 6, 2021, Capitol breach, leading to the Electoral Count Reform Act of 2022 which clarified the vice president\'s role as purely ceremonial.' },
  { id: 'pres-123', category: 'presidents', difficulty: 'hard', question: 'What president served as head of the CIA before becoming president?', answer: 'George H.W. Bush', options: ['Richard Nixon', 'George H.W. Bush', 'Dwight Eisenhower', 'Gerald Ford'], explanation: 'George H.W. Bush served as Director of Central Intelligence from 1976 to 1977 under President Ford. He also served as ambassador to the United Nations and envoy to China before becoming Reagan\'s vice president.' },
  { id: 'pres-124', category: 'presidents', difficulty: 'hard', question: 'What Supreme Court case established that students do not lose their constitutional rights at school?', answer: 'Tinker v. Des Moines', options: ['Brown v. Board of Education', 'Tinker v. Des Moines', 'Engel v. Vitale', 'New Jersey v. T.L.O.'], explanation: 'Tinker v. Des Moines (1969) ruled that students wearing black armbands to protest the Vietnam War was protected speech. Justice Abe Fortas wrote that students do not "shed their constitutional rights to freedom of speech or expression at the schoolhouse gate."' },
  { id: 'pres-125', category: 'presidents', difficulty: 'hard', question: 'What president was the first to appear on television?', answer: 'Franklin D. Roosevelt', options: ['Harry Truman', 'Franklin D. Roosevelt', 'Dwight Eisenhower', 'Calvin Coolidge'], explanation: 'FDR appeared on an experimental NBC broadcast at the 1939 New York World\'s Fair, becoming the first president on television. However, it was the 1960 Kennedy-Nixon debates that truly demonstrated television\'s power in politics.' },
]
